CREATE TABLE support_ticket(id uuid PRIMARY KEY,customer_subject varchar(160) NOT NULL,order_id uuid,subject varchar(160) NOT NULL,status varchar(24) NOT NULL DEFAULT 'OPEN' CHECK(status IN ('OPEN','IN_PROGRESS','WAITING_FOR_CUSTOMER','RESOLVED')),revision bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX support_ticket_owner_idx ON support_ticket(customer_subject,updated_at DESC);
CREATE TABLE support_message(id uuid PRIMARY KEY,ticket_id uuid NOT NULL REFERENCES support_ticket(id),operation_id uuid NOT NULL UNIQUE,actor_subject varchar(160) NOT NULL,audience varchar(16) NOT NULL CHECK(audience IN ('CUSTOMER','OPERATOR')),body varchar(4000) NOT NULL,request_hash char(64) NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE support_audit(id uuid PRIMARY KEY,ticket_id uuid NOT NULL REFERENCES support_ticket(id),actor_subject varchar(160) NOT NULL,previous_status varchar(24),next_status varchar(24) NOT NULL,reason varchar(500) NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
